DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT102-S3-Q14$batch01$ AND c.letter=$batch01$A$batch01$ AND c.choice_text=$batch01$attempts to force acceptance of a claim by inducing fear of the consequences of rejecting that claim$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT102-S3-Q14 A'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT102-S3-Q14$batch01$ AND c.letter=$batch01$B$batch01$ AND c.choice_text=$batch01$bases a conclusion on claims that are inconsistent with each other$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT102-S3-Q14 B'; END IF; END $guard$;
