DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanation_steps s JOIN lr_explanations e ON e.id=s.explanation_id JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT102-S3-Q14$batch01$ AND e.style IN ('single','standard')) <> 4 OR (SELECT COUNT(*) FROM lr_explanation_choice_notes n JOIN lr_explanations e ON e.id=n.explanation_id JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT102-S3-Q14$batch01$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation changed: PT102-S3-Q14'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT102-S3-Q14$batch01$ AND e.id=$batch01$1a6dea07-9e31-47d5-9577-b87cd1a4eec1$batch01$ AND e.style=$batch01$standard$batch01$) THEN RAISE EXCEPTION 'Target explanation changed: PT102-S3-Q14'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanation_steps s WHERE s.explanation_id=$batch01$1a6dea07-9e31-47d5-9577-b87cd1a4eec1$batch01$ AND (s.id::text,s.position,s.label,s.body) IN (VALUES ($batch01$54fa7506-43f4-4a82-8f8b-475ca86da8fa$batch01$, 0, $batch01$Conclusion (So)$batch01$, $batch01$There is no reason not to try my herb juice.$batch01$), ($batch01$db9d9905-a22f-4c4a-97c3-90abd0b9c891$batch01$, 1, $batch01$Evidence$batch01$, $batch01$Customers report improved physical coordination.
  A few doctors say the herbs are potentially harmful, but doctors are always trying to maintain a monopoly over medical therapies.$batch01$), ($batch01$bfbb2fa9-f17a-41dd-ae12-f53af0c9af03$batch01$, 2, $batch01$Evaluate$batch01$, $batch01$If we're the other lawyer and we're arguing,
*there IS some reason not to try this herb juice*
what would we say?
  We could start with, "wait — some doctors said the juice was harmful? That would be a reason not to try it."
  And the author will say, "Oh, don't listen to them. Doctors don't want herbs to work. They want a monopoly over medicine, so they talk smack about anything that isn't pharmaceuticals."
  We need a response. We could say, "Sure, I would imagine that Big Pharma is incentivized to diminish non-pharmaceutical treatments. Buuuut, we can't just ignore warnings that something is harmful. What if it's actually harmful? Do you have evidence it's safe?"
  If we know our Famous Flaws, then we'll hopefully recognize this as a classic Ad Hominem. That's when the author dismisses someone's view because they (1) have an ulterior motive / vested interest, or (2) have conflicting past behavior / hypocrisy.
  In this case, the author is trying to immediately disqualify what these doctors are saying just because doctors do have a financial interest in herbal treatments being bad ideas.$batch01$), ($batch01$1c0d8000-8f52-451a-8497-28414f832400$batch01$, 3, $batch01$Goal$batch01$, $batch01$Look for an answer addressing the Ad Hominem move where the author fails to seriously address the concerns of the doctors and wipes them away by pointing out their self-interest.
  Or, there might be an answer saying, "even if the herb juice isn't harmful, there still might be some *other* reason not to try it" (e.g. its awful taste, the farts it gives you, etc.)$batch01$))) <> 4 THEN RAISE EXCEPTION 'Existing step changed: PT102-S3-Q14'; END IF; END $guard$;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch01$A$batch01$, $batch01$The herbalist does not warn customers of frightening consequences if they reject the juice. The doctors' warning that the herbs might be harmful is the point the herbalist dismisses.$batch01$), ($batch01$B$batch01$, $batch01$Customers can report improved coordination while the herbs still carry a risk of harm. Those claims can both be true, so the herbalist's evidence is not internally inconsistent.$batch01$), ($batch01$C$batch01$, $batch01$The doctors assert that the herbs might be harmful. The herbalist replies that doctors want to protect a monopoly, then concludes there is no reason not to try the juice. A motive to make a claim does not show that the claim is false. The potential harm has not been addressed. This is the Ad Hominem move.$batch01$), ($batch01$D$batch01$, $batch01$The customer reports are not phrased to assume the juice is safe. The error occurs in dismissing the warning, not in wording the evidence as the conclusion.$batch01$), ($batch01$E$batch01$, $batch01$The report that coordination improves *after* drinking juice might invite a post hoc objection if the conclusion were that the juice caused the improvement. The conclusion is that there is **no reason not to try** it. The live objection is the possible harm raised by doctors, and the herbalist attacks the doctors instead.$batch01$)) v(letter,body) WHERE q.qid=$batch01$PT102-S3-Q14$batch01$ AND e.id=$batch01$1a6dea07-9e31-47d5-9577-b87cd1a4eec1$batch01$ AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id) ON CONFLICT DO NOTHING;
COMMIT;
